arguments:
$ErrorActionPreference = 'Stop'
$thumbprint = '7B0F360B775F76C94A12CA48445AA2D2A875701C'
$outputPath = 'C:\Assets\AssetValidation\AssetValidation-20260904T103354\DigiCert-Trusted-G4-CodeSigning-2021-CA1-7B0F360B.cer'
if (Test-Path -LiteralPath $outputPath) { throw ('Refusing to overwrite: ' + $outputPath) }
$cert = Get-Item -LiteralPath ('Cert:\CurrentUser\CA\' + $thumbprint)
if ($cert.Thumbprint -ne $thumbprint) { throw 'Certificate thumbprint mismatch' }
if ($cert.Subject -notmatch 'DigiCert Trusted G4 Code Signing RSA4096 SHA384 2021 CA1') { throw ('Unexpected certificate subject: ' + $cert.Subject) }
Export-Certificate -Cert $cert -FilePath $outputPath -Type CERT | Out-Null
$file = Get-Item -LiteralPath $outputPath
[pscustomobject]@{OutputPath=$file.FullName;Length=$file.Length;SHA256=(Get-FileHash -LiteralPath $outputPath -Algorithm SHA256).Hash;Subject=$cert.Subject;Issuer=$cert.Issuer;Thumbprint=$cert.Thumbprint;NotAfter=$cert.NotAfter.ToString('o')} | Format-List
